#include "ddb/storage/physical_mutation.h"
#include <algorithm>
#include <cstring>
#include <stdexcept>
namespace ddb::storage { namespace {std::vector<std::byte> image(ddb::buffer::BufferPoolManager&p,PageId id){auto*x=p.fetch_page(id);if(!x)throw std::runtime_error("cannot fetch mutation page");std::vector<std::byte> out(x->data(),x->data()+x->payload_size());if(!p.unpin_page(id,false))throw std::runtime_error("cannot unpin mutation page");return out;}void apply(ddb::buffer::BufferPoolManager&p,const PhysicalMutation&m,const std::vector<std::byte>& bytes){if(bytes.size()!=kPagePayloadSize)throw std::invalid_argument("invalid mutation payload image");auto*x=p.fetch_page(m.page_id);if(!x)throw std::runtime_error("cannot fetch replay page");std::memcpy(x->data(),bytes.data(),bytes.size());if(!p.unpin_page(m.page_id,true))throw std::runtime_error("cannot unpin replay page");}}
MutationContext::MutationContext(ddb::buffer::BufferPoolManager&p):pool_(p){}void MutationContext::watch(PageId id){if(!id.is_valid())throw std::invalid_argument("invalid mutation page");pending_.push_back({id,image(pool_,id)});}void MutationContext::finish(PageId id){auto it=std::find_if(pending_.begin(),pending_.end(),[&](const Pending&p){return p.id==id;});if(it==pending_.end())throw std::logic_error("finish without watch");auto after=image(pool_,id);if(after!=it->before)mutations_.push_back({id,MutationKind::PayloadWrite,next_sequence_++,std::move(it->before),std::move(after)});pending_.erase(it);}std::vector<PhysicalMutation> MutationContext::finalize(){if(!pending_.empty())throw std::logic_error("unfinished mutation capture");return std::move(mutations_);}void apply_after_image(ddb::buffer::BufferPoolManager&p,const PhysicalMutation&m){apply(p,m,m.after_image);}void apply_before_image(ddb::buffer::BufferPoolManager&p,const PhysicalMutation&m){apply(p,m,m.before_image);}
}
